(SELECT identity, opponentIdentity, gameId, potTxid, potVout, recoveryHeight, seatSettlePubkey, seatSigHex, sigHex, createdAt, rowid AS markerRowid, sigValid FROM potparty_records WHERE identity = ?1 UNION ALL SELECT hp.identity AS identity, hp.opponentIdentity AS opponentIdentity, hp.gameId AS gameId, pot.txid AS potTxid, pot.outputIndex AS potVout, pot.recoveryHeight AS recoveryHeight, hp.seatSettlePubkey AS seatSettlePubkey, hp.seatSigHex AS seatSigHex, hp.identitySigHex AS sigHex, hp.createdAt AS createdAt, hp.rowid AS markerRowid, hp.markerValid AS sigValid FROM hopparty_records hp JOIN pot_records hop ON hop.txid = hp.txid AND hop.outputIndex = hp.hopVout JOIN pot_records pot ON pot.txid = lower(hop.spendingTxid) AND pot.outputIndex = 0 WHERE hp.identity = ?1 AND hp.markerValid = 1 AND hop.spent = 1 AND hop.spendingTxid IS NOT NULL AND pot.paramsDecoded = 1 AND pot.recoveryHeight IS NOT NULL AND pot.pubA IS NOT NULL AND pot.pubB IS NOT NULL AND lower(hp.seatSettlePubkey) IN (lower(pot.pubA), lower(pot.pubB)) AND NOT EXISTS (SELECT 1 FROM potparty_records x WHERE x.identity = hp.identity AND x.potTxid = pot.txid AND x.potVout = pot.outputIndex))